async function persist(){if(!doc)return;syncPage(doc);const seq=++saveSeq,copy=clone(doc);copy.schemaVersion=2;copy.updated=Date.now();const i=docs.findIndex(d=>d.id===copy.id);if(i>=0)docs[i]=copy;else docs.push(copy);$('#saveStatus').textContent='Salvando…';try{await saveDocument(db,copy,docs);try{localStorage.setItem('catastrophe-current',copy.id);}catch{}if(db)saveVersion(db,copy,'Recuperação automática',true).catch(()=>{});if(seq===saveSeq)$('#saveStatus').textContent='Salvo neste navegador às '+new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});}catch(err){$('#saveStatus').textContent='Erro ao salvar';toast('Erro ao salvar: '+err.message+'. Exporte um backup JSON.');}}
function scheduleSave(){clearTimeout(saveTimer);$('#saveStatus').textContent='Salvando…';saveTimer=setTimeout(persist,350);}
function history(force=false){const field=document.activeElement;const key=!force&&field?.matches('input,textarea,select')?field.tagName+':'+Object.entries(field.dataset).map(([k,v])=>k+'='+v).join(';')+':'+(selected||doc.id):null;timeline.record(snapshot(),key);updateHistory();}
function updateHistory(){$('#undoBtn').disabled=!timeline.undo.length;$('#redoBtn').disabled=!timeline.redo.length;$$('.composition-tools [data-studio="undo"]').forEach(b=>b.disabled=!timeline.undo.length);$$('.composition-tools [data-studio="redo"]').forEach(b=>b.disabled=!timeline.redo.length);}
function change(fn,panels=false,force=false){history(force);const previous=selected;try{fn();if(doc.flowMode==='flow')for(const b of doc.blocks.slice().sort((a,b)=>a.y-b.y))if(!b.locked&&['text','ability','profile','ritualPart','equipment'].includes(b.type))growBlock(doc,b,source.skills);syncPage(doc);}catch(err){const old=timeline.restore('undo',snapshot());if(old){doc=old.document;selection.clear();old.selection.forEach(id=>selection.add(id));selected=old.selected;}toast(err.message);return;}if(previous!==selected&&!selection.has(selected)){selection.clear();if(selected)selection.add(selected);}doc.updated=Date.now();draw();scheduleSave();if(panels){renderLeft();renderInspector();}else updateBudget();}
function restore(from,to){if(mode!=='edit')return;const direction=from===undo?'undo':'redo',state=timeline.restore(direction,snapshot());if(!state)return;doc=state.document;const restored=restoreSelection(state,doc);selected=restored.selected;selection.clear();restored.selection.forEach(id=>selection.add(id));draw();renderLeft();renderInspector();scheduleSave();updateHistory();}
